import java.util.*;

class Solution {
  private static final int INF = Integer.MAX_VALUE / 2;

  public int minimumValueSum(int[] nums, int[] andValues) {
    int n = nums.length;
    // for each end e: the distinct ANDs of subarrays ending at e, each with the leftmost start producing it
    // (extending left only clears bits, so there are at most ~17 of them)
    int[][] runVal = new int[n][], runLo = new int[n][];
    int[] curVal = new int[0], curLo = new int[0];
    for (int e = 0; e < n; e++) {
      int[] v = new int[curVal.length + 1], lo = new int[curVal.length + 1];
      v[0] = nums[e];
      lo[0] = e;
      int size = 1;
      for (int i = 0; i < curVal.length; i++) {
        int a = curVal[i] & nums[e];
        if (a == v[size - 1]) lo[size - 1] = curLo[i];
        else {
          v[size] = a;
          lo[size] = curLo[i];
          size++;
        }
      }
      curVal = runVal[e] = Arrays.copyOf(v, size);
      curLo = runLo[e] = Arrays.copyOf(lo, size);
    }
    // prev[s]: cheapest way to cut nums[0..s) into the groups handled so far
    int[] prev = new int[n + 1];
    Arrays.fill(prev, INF);
    prev[0] = 0;
    for (int target : andValues) {
      SparseMin table = new SparseMin(prev);
      int[] next = new int[n + 1];
      Arrays.fill(next, INF);
      for (int e = 0; e < n; e++) {
        int hi = e;
        for (int r = 0; r < runVal[e].length; r++) {
          int lo = runLo[e][r];
          if (runVal[e][r] == target) {
            // every start in [lo, hi] gives this AND, so take the cheapest prefix among them
            int best = table.min(lo, hi);
            if (best < INF) next[e + 1] = best + nums[e];
            break;
          }
          hi = lo - 1;
        }
      }
      prev = next;
    }
    return prev[n] >= INF ? -1 : prev[n];
  }

  static class SparseMin {
    private final int[][] table;
    private final int[] log;

    SparseMin(int[] a) {
      int n = a.length;
      log = new int[n + 1];
      for (int i = 2; i <= n; i++) log[i] = log[i / 2] + 1;
      table = new int[log[n] + 1][];
      table[0] = a.clone();
      for (int k = 1; k < table.length; k++) {
        table[k] = new int[n - (1 << k) + 1];
        for (int i = 0; i < table[k].length; i++)
          table[k][i] = Math.min(table[k - 1][i], table[k - 1][i + (1 << (k - 1))]);
      }
    }

    int min(int lo, int hi) {
      int k = log[hi - lo + 1];
      return Math.min(table[k][lo], table[k][hi - (1 << k) + 1]);
    }
  }
}
